WITH flattened AS (SELECT id, service, level, latency_ms, status_code, k, v FROM app_logs LATERAL VIEW EXPLODE(context) x AS k, v), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY service ORDER BY status_code DESC, id, k) AS latest_rank FROM flattened) t WHERE latest_rank = 1), base AS (SELECT *, ROUND(latency_ms * 0.85, 2) AS latency_ms_scaled FROM deduped WHERE k <> 'region'), with_windows AS (SELECT *, LEAD(latency_ms) OVER w_recent AS next_latency_ms, LAG(status_code) OVER w_recent AS prev_status_code, ROW_NUMBER() OVER w_recent AS event_seq FROM base WINDOW w_recent AS (PARTITION BY service, k ORDER BY status_code, id, k)) SELECT level, CASE WHEN status_code >= 459 THEN 'LARGE' ELSE 'SMALL' END AS status_code_tier, SORT_ARRAY(COLLECT_SET(service)) AS service_list, APPROX_PERCENTILE(event_seq, ARRAY(0.25, 0.5, 0.75)) AS event_seq_quartiles FROM with_windows GROUP BY level, CASE WHEN status_code >= 459 THEN 'LARGE' ELSE 'SMALL' END;
